// Single import point for exported physics data (generated by physics/validate/export.py).
import thermoJson from "@/data/thermo.json";
import propertiesJson from "@/data/properties.json";
import dropletParams from "@/data/params/droplet.json";
import suppressionParams from "@/data/params/suppression.json";
import limitsJson from "@/data/limits.json";

/* eslint-disable @typescript-eslint/no-explicit-any */
export const THERMO = thermoJson as unknown as {
  nasa7: Record<string, { T_mid: number; high: number[]; low: number[] }>;
  M: Record<string, number>;
};
export const PROPS = propertiesJson as any;
export const DROPLET_PARAMS = dropletParams as any;
export const SUPPRESSION_PARAMS = suppressionParams as any;
export const LIMITS = limitsJson as any;

export type Atm = Record<string, number>;
export type Formula = Record<string, number>;

export function prop(...path: string[]): number {
  let node: any = PROPS;
  for (const p of path) node = node[p];
  return typeof node === "object" ? Number(node.value) : Number(node);
}

export function fuel(name: string): any {
  const f = PROPS.fuels[name];
  if (!f) throw new Error(`unknown fuel/material ${name}`);
  return f;
}

export function v(f: any, key: string): number {
  return Number(f[key].value);
}
